/*
 * Shared helpers for the Blush design (header, footer, home and article pages).
 *
 * The Blush stylesheet (app/blush.css, generated by scripts/build-blush-css.mjs) prefixes every class with
 * "bl-" and scopes every rule under .blush, so it cannot touch the Magzin pages that share the site. `b()`
 * writes the prefixed names: b('hero__title txt-d') -> 'bl-hero__title bl-txt-d'.
 */
export const b = (classes: string): string =>
  classes
    .split(/\s+/)
    .filter(Boolean)
    .map((token) => `bl-${token}`)
    .join(' ');

/** First path segments whose two-segment URLs belong to the Magzin pages, not to articles. */
const NOT_ARTICLE_ROOTS = new Set(['products', 'brands', 'categories', 'authors', 'legal', 'api']);

/**
 * Pages drawn in the Blush chrome: the home page and every article (/<hub>/<slug>). The root layout renders the
 * Magzin header and footer for everything else.
 */
export function isBlushPath(pathname: string | null | undefined): boolean {
  if (!pathname) return false;
  const path = pathname.replace(/\/+$/, '') || '/';
  if (path === '/') return true;
  const parts = path.split('/').filter(Boolean);
  return parts.length === 2 && !NOT_ARTICLE_ROOTS.has(parts[0]);
}
